import{_ as o,C as r,o as n,c as d,a2 as s,b as l,w as a,a as p,E as i,a3 as g}from"./chunks/framework.BC3NdntU.js";const _=JSON.parse('{"title":"11.8 底层逻辑打通:统一框架","description":"","frontmatter":{},"headers":[],"relativePath":"卷十一-AIAgentHarness与提示词工程/11.8-底层逻辑打通统一框架.md","filePath":"卷十一-AIAgentHarness与提示词工程/11.8-底层逻辑打通统一框架.md","lastUpdated":1788794271000}'),u={name:"卷十一-AIAgentHarness与提示词工程/11.8-底层逻辑打通统一框架.md"};function h(q,t,b,c,A,E){const e=r("Mermaid");return n(),d("div",null,[t[1]||(t[1]=s('<h1 id="_11-8-底层逻辑打通-统一框架" tabindex="-1">11.8 底层逻辑打通:统一框架 <a class="header-anchor" href="#_11-8-底层逻辑打通-统一框架" aria-label="Permalink to &quot;11.8 底层逻辑打通:统一框架&quot;">​</a></h1><blockquote><p>卷:卷十一 · AI Agent Harness 与提示词工程 难度:⭐⭐⭐ 专家(收束) | 阅读时间:30min</p></blockquote><hr><h2 id="引言-七章之后-把它们焊成-一个模型" tabindex="-1">引言:七章之后,把它们焊成&quot;一个模型&quot; <a class="header-anchor" href="#引言-七章之后-把它们焊成-一个模型" aria-label="Permalink to &quot;引言:七章之后,把它们焊成&quot;一个模型&quot;&quot;">​</a></h2><p>前面七章分别讲了引擎、循环、运行时、上下文、工具、提示词。这一章把它们<strong>收束成一个统一框架</strong>,让你离开时脑子里只有一张图、一句话。</p><hr><h2 id="一、一张总图-agent-的四要素-一个循环" tabindex="-1">一、一张总图:Agent 的四要素 + 一个循环 <a class="header-anchor" href="#一、一张总图-agent-的四要素-一个循环" aria-label="Permalink to &quot;一、一张总图:Agent 的四要素 + 一个循环&quot;">​</a></h2>',7)),(n(),l(g,null,{default:a(()=>[i(e,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20H%5BHarness%20%E8%BF%90%E8%A1%8C%E6%97%B6%3Cbr%2F%3E%E7%8A%B6%E6%80%81%E6%9C%BA%20%2B%20%E5%AE%B9%E9%94%99%20%2B%20%E8%A7%82%E6%B5%8B%5D%0A%20%20%20%20H%20--%3E%20P%5BPrompt%20%E6%84%8F%E5%9B%BE%2F%E7%BA%A6%E6%9D%9F%3Cbr%2F%3E%E6%96%B9%E5%90%91%E7%9B%98%5D%0A%20%20%20%20H%20--%3E%20C%5BContext%20%E7%8A%B6%E6%80%81%2F%E8%AE%B0%E5%BF%86%3Cbr%2F%3E%E8%AE%B0%E5%BF%86%5D%0A%20%20%20%20H%20--%3E%20T%5BTools%20%E8%83%BD%E5%8A%9B%3Cbr%2F%3E%E6%89%8B%E8%84%9A%5D%0A%20%20%20%20P%20%26%20C%20%26%20T%20--%3E%20L%5BLLM%20%E5%BC%95%E6%93%8E%3Cbr%2F%3Enext-token%20%E9%A2%84%E6%B5%8B%5D%0A%20%20%20%20L%20--%3E%20A%5B%E5%86%B3%E7%AD%96%3A%E6%80%9D%E8%80%83%20%2B%20%E8%A1%8C%E5%8A%A8%5D%0A%20%20%20%20A%20--%3E%7C%E8%B0%83%E7%94%A8%E5%B7%A5%E5%85%B7%7C%20T%0A%20%20%20%20T%20--%3E%20O%5B%E8%A7%82%E5%AF%9F%20Observation%5D%0A%20%20%20%20O%20--%3E%20C%0A%20%20%20%20O%20--%3E%20A%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[p(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=s(`<p><strong>四个要素,对应一个朴素的比喻(11.1 埋下的伏笔):</strong></p><table tabindex="0"><thead><tr><th>要素</th><th>比喻</th><th>负责什么</th><th>对应章节</th></tr></thead><tbody><tr><td><strong>LLM</strong></td><td>发动机</td><td>只提供&quot;预测下一个 token&quot;的算力与智能</td><td>11.1</td></tr><tr><td><strong>Prompt</strong></td><td>方向盘</td><td>意图、约束、格式(往哪走、怎么走)</td><td>11.6 / 11.7</td></tr><tr><td><strong>Tools</strong></td><td>手脚</td><td>碰触外部世界的能力</td><td>11.5</td></tr><tr><td><strong>Context</strong></td><td>记忆</td><td>状态、历史、检索来的知识</td><td>11.4</td></tr><tr><td><strong>Harness</strong></td><td>车身 + 车手</td><td>把这四者串成<strong>可循环、可容错、可观测</strong>的系统</td><td>11.2 / 11.3</td></tr></tbody></table><hr><h2 id="二、一句话总结整个领域" tabindex="-1">二、一句话总结整个领域 <a class="header-anchor" href="#二、一句话总结整个领域" aria-label="Permalink to &quot;二、一句话总结整个领域&quot;">​</a></h2><blockquote><p><strong>Agent = 一个&quot;有记忆、有手脚、有方向&quot;的 next-token 预测器,被一个容错的循环(Harness)驱动着反复&quot;思考→行动→观察&quot;,直到达成目标。</strong></p></blockquote><p>拆开就是三个判断:</p><ol><li><strong>本质</strong>:LLM 只会预测下一个 token(11.1)——所有&quot;智能&quot;都是它的涌现</li><li><strong>放大</strong>:给它工具(能做)、上下文(能记)、提示词(能引导),能力才被放大(11.4~11.7)</li><li><strong>收敛</strong>:用 Harness 的循环 + 容错把它变成<strong>可靠</strong>的系统(11.2 / 11.3)</li></ol><hr><h2 id="三、openai-的视角-人类掌舵-智能体执行" tabindex="-1">三、OpenAI 的视角:&quot;人类掌舵,智能体执行&quot; <a class="header-anchor" href="#三、openai-的视角-人类掌舵-智能体执行" aria-label="Permalink to &quot;三、OpenAI 的视角:&quot;人类掌舵,智能体执行&quot;&quot;">​</a></h2><p>OpenAI 那篇 harness-engineering 博客,给了这个领域一个更高维的定调:</p><blockquote><p><strong>&quot;人类掌舵,智能体执行。&quot;(Humans steer, agents execute.)</strong></p></blockquote><p>它的完整推演链:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>工程的主要工作,从&quot;写代码&quot; → 变成&quot;设计环境、明确意图、构建反馈回路&quot;</span></span>
<span class="line"><span>                                          (让 Agent 能可靠地工作)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>三个关键词正好映射本卷三块:</strong></p><table tabindex="0"><thead><tr><th>博客关键词</th><th>本卷对应</th><th>含义</th></tr></thead><tbody><tr><td><strong>设计环境</strong></td><td>11.3 Harness + 11.4 上下文</td><td>给 Agent 一个&quot;能读、能查、能改&quot;的结构化世界(仓库即记录系统)</td></tr><tr><td><strong>明确意图</strong></td><td>11.6/11.7 提示词</td><td>把目标、约束、验收标准讲清楚(地图而非说明书)</td></tr><tr><td><strong>构建反馈回路</strong></td><td>11.2 循环 + 11.5 工具</td><td>让 Agent 能观察结果、自我纠错、循环推进</td></tr></tbody></table><p><strong>它最硬的一句(收束点):</strong></p><blockquote><p><strong>&quot;构建软件仍然需要纪律,但纪律更多地体现在支撑结构上,而不是代码上。保持代码库一致性的工具、抽象和反馈回路变得越发重要。&quot;</strong></p></blockquote><p>这句话反过来读就是本卷的全部:<strong>Agent 工程的竞争力,不在模型,而在你为它搭建的&quot;支撑结构&quot;——Harness、上下文、工具、提示词。</strong></p><hr><h2 id="四、从-会用-到-会设计-的三个层次" tabindex="-1">四、从&quot;会用&quot;到&quot;会设计&quot;的三个层次 <a class="header-anchor" href="#四、从-会用-到-会设计-的三个层次" aria-label="Permalink to &quot;四、从&quot;会用&quot;到&quot;会设计&quot;的三个层次&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层次</th><th>你在做什么</th><th>对应能力</th></tr></thead><tbody><tr><td>L1 会调</td><td>写好 prompt,拿到好答案</td><td>11.6/11.7</td></tr><tr><td>L2 会搭</td><td>给模型接工具、跑循环</td><td>11.2/11.5</td></tr><tr><td>L3 会设计</td><td>设计环境、约束、反馈回路,让<strong>一群</strong> Agent 可靠协作</td><td>11.3/11.4 + 11.8</td></tr></tbody></table><blockquote><p>大多数人停在 L1(调 prompt);真正拉开差距的是 <strong>L2 的循环 + L3 的环境设计</strong>——这也是&quot;harness engineering&quot;这个词真正的分量所在。</p></blockquote><hr><h2 id="五、落地清单-判断一个-agent-系统靠不靠谱" tabindex="-1">五、落地清单:判断一个 Agent 系统靠不靠谱 <a class="header-anchor" href="#五、落地清单-判断一个-agent-系统靠不靠谱" aria-label="Permalink to &quot;五、落地清单:判断一个 Agent 系统靠不靠谱&quot;">​</a></h2><p>用本卷的框架,快速评估任何 Agent 系统:</p><ol><li><strong>循环有没有兜底?</strong> 步数上限?终止条件?死循环检测?(11.2)</li><li><strong>容错是否分层?</strong> 超时 → 退避重试 → 错误再入 → 降级?(11.3)</li><li><strong>上下文是否克制?</strong> 地图还是说明书?渐进式披露?记忆分层?(11.4)</li><li><strong>工具是否设防?</strong> 最小权限?沙箱?高风险人工确认?防注入?(11.5)</li><li><strong>输出是否可解析?</strong> 锁格式?低温?结构化输出?(11.6)</li><li><strong>事实是否靠工具锚定?</strong> 还是让模型&quot;记&quot;?(11.1/11.5)</li><li><strong>人是否在关键环上?</strong> 人类掌舵、审关键决策?(11.8)</li></ol><hr><h2 id="六、小结" tabindex="-1">六、小结 <a class="header-anchor" href="#六、小结" aria-label="Permalink to &quot;六、小结&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>统一框架:LLM(引擎)+ Prompt(方向盘)+ Tools(手脚)+ Context(记忆)</span></span>
<span class="line"><span>          └─ 由 Harness(车身/车手)串成&quot;思考→行动→观察&quot;的容错循环</span></span>
<span class="line"><span></span></span>
<span class="line"><span>一句话:Agent = 有记忆、有手脚、有方向的 next-token 预测器,被容错循环驱动直到达成目标</span></span>
<span class="line"><span></span></span>
<span class="line"><span>OpenAI 定调:人类掌舵,智能体执行</span></span>
<span class="line"><span>             → 工程重心 = 设计环境 + 明确意图 + 构建反馈回路</span></span>
<span class="line"><span>             → 纪律在&quot;支撑结构&quot;,不在&quot;代码&quot;</span></span>
<span class="line"><span>层次:会调(prompt)&lt; 会搭(循环/工具)&lt; 会设计(环境/约束/反馈回路)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><hr><h2 id="七、终章思考题" tabindex="-1">七、终章思考题 <a class="header-anchor" href="#七、终章思考题" aria-label="Permalink to &quot;七、终章思考题&quot;">​</a></h2><p><strong>Q1:用一段话向一个&quot;只会用 ChatGPT 聊天&quot;的人解释什么是 Agent。</strong></p><p>模型本身只会&quot;接话&quot;(预测下一个词)。Agent 是给这个模型装了<strong>手脚(工具)、记忆(上下文)、方向盘(提示词)</strong>,再套上一个<strong>循环(反复&quot;思考→行动→观察&quot;)</strong>,让它从&quot;只会聊天&quot;变成&quot;能查、能写、能执行、能自我纠错&quot;的任务机器。</p><p><strong>Q2:为什么说&quot;Agent 的竞争力在支撑结构,而非模型&quot;?</strong></p><p>因为模型的<strong>能力是外部的、大家都一样</strong>(都能调同一个模型);真正决定一个 Agent 系统好不好用的是你<strong>为它搭建的环境</strong>:上下文怎么组织、工具怎么设防、循环怎么容错、反馈回路怎么建。模型决定上限,支撑结构决定<strong>你能不能稳定地接近那个上限</strong>——这正是 harness engineering 的意义。</p><p><strong>Q3:本卷的&quot;一张图、一句话&quot;分别是什么?</strong></p><p><strong>一张图</strong>:LLM 引擎 + Prompt 方向盘 + Tools 手脚 + Context 记忆,被 Harness 的循环(思考→行动→观察)驱动。<strong>一句话</strong>:Agent 是一个有记忆、有手脚、有方向的 next-token 预测器,被容错循环驱动直到达成目标。</p><hr><p>📎 参考:OpenAI《harness-engineering》博客、Anthropic《Building Effective Agents》、本卷 11.1~11.7</p>`,39))])}const B=o(u,[["render",h]]);export{_ as __pageData,B as default};
